public NanoHTTPD.Response serve(NanoHTTPD server, Properties parms, RequestType type) {
  switch (type) {
    case help:    return wrap(server, HTMLHelp());
    case json: case www:  return serveGrid(server, parms, type);
    case query: {
      for (Argument arg : _arguments) arg.reset();
      String query = null;
      try {
        query = buildQuery(parms, type);
      } catch (RuntimeException | IndexOutOfBoundsException e) {
        // Handle the exception, e.g., log it or return a specific response
        return newFixedLengthResponse(Response.Status.INTERNAL_ERROR, MIME_PLAINTEXT, e.getMessage());
      }
      return wrap(server, query);
    }
    case java: 
      checkArguments(parms, type);
      String javacode = serveJava();
      return wrap(server, javacode, RequestType.java);
    default: 
      throw new RuntimeException("Invalid request type " + type.toString());
  }
}
